PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS owner (id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, session_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS babies (id TEXT PRIMARY KEY, name TEXT NOT NULL, birthday TEXT NOT NULL, gender TEXT NOT NULL CHECK(gender IN ('girl','boy','other')), time_zone TEXT NOT NULL DEFAULT 'Asia/Shanghai', allergies TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS growth_records (id TEXT PRIMARY KEY, baby_id TEXT NOT NULL REFERENCES babies(id) ON DELETE CASCADE, day TEXT NOT NULL, weight REAL, height REAL, head_circumference REAL, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS growth_by_day ON growth_records(baby_id,day DESC);
CREATE TABLE IF NOT EXISTS milestones (id TEXT PRIMARY KEY, baby_id TEXT NOT NULL REFERENCES babies(id) ON DELETE CASCADE, day TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS milestones_by_day ON milestones(baby_id,day DESC);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, baby_id TEXT NOT NULL REFERENCES babies(id) ON DELETE CASCADE, day TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', object_key TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS media_by_day ON media(baby_id,day DESC);
CREATE TABLE IF NOT EXISTS app_settings (name TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts (ip_hash TEXT PRIMARY KEY, tries INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS wechat_messages (message_id TEXT PRIMARY KEY, state TEXT NOT NULL, created_at TEXT NOT NULL);
